insert into public.topics (slug, title, description, position)
values ($g0$pronouns$g0$, $g1$Займенники (Pronouns & Determiners)$g1$, $g2$Особові, присвійні та зворотні займенники, each other, вказівні this/that, кількісні many/much/few/little, some/any/no/every, other/another, both/all/none/either/neither/each.$g2$, 6)
