insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g3$th_hero$g3$, $g4$Займенники$g4$, $g5$elementary$g5$, $g6$hero$g6$, $g7${"title":"Pronouns & Determiners","chips":["Англійська граматика","Займенники"],"lead":"Займенник <b>замінює</b> іменник, щоб не повторюватися. Детермінант стоїть <b>перед</b> іменником і уточнює, який він чи скільки його. Багато слів можуть бути і тим, і тим.","diagramTitle":"Дві ролі","diagram":[{"role":"замінює іменник","label":"Anna → she","tone":"opinion"},{"role":"стоїть перед іменником","label":"this book · many books","tone":"colour"}],"diagramJoin":"або","diagramNote":"this, some, both — можуть і те, і те"}$g7$::jsonb, null, 0
