insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g9$th_1$g9$, $g10$Займенники та детермінанти: загальна карта$g10$, $g11$elementary$g11$, $g12$cases$g12$, $g13${"step":"Карта","kicker":"Базове розуміння","lead":"Займенників кілька родин. Кожна відповідає на своє питання — від «хто?» до «скільки?».","cards":[{"icon":"☺","title":"Особові","text":"Хто діє і на кого спрямована дія: I, me, you, he, him…","example":"<b>She</b> called <b>him</b>.","examplePlain":"She called him."},{"icon":"◆","title":"Присвійні","text":"Чиє? Перед іменником (my) або замість нього (mine).","example":"It's <b>my</b> pen. It's <b>mine</b>.","examplePlain":"It's my pen. It's mine."},{"icon":"↺","title":"Зворотні","text":"Дія повертається на того, хто її виконує: myself, yourself…","example":"I cut <b>myself</b>.","examplePlain":"I cut myself."},{"icon":"⇄","title":"Взаємні","text":"Дія спрямована одне на одного: each other, one another.","example":"We've known <b>each other</b> for years.","examplePlain":"We've known each other for years."},{"icon":"⌖","title":"Вказівні","text":"Який саме — тут чи там: this, these, that, those.","example":"<b>This</b> dress is mine.","examplePlain":"This dress is mine."},{"icon":"∑","title":"Неозначені й кількісні","text":"Хтось, щось, скільки: some, any, no, every, much, many, few, other, both, all, each…","example":"<b>some</b>one · <b>many</b> books · <b>both</b> of them","examplePlain":"someone, many books, both of them"}]}$g13$::jsonb, null, 1
