insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g15$th_2$g15$, $g16$Особові займенники: підмет і додаток$g16$, $g17$elementary$g17$, $g18$pairs$g18$, $g19${"step":"Особові","kicker":"Дві форми","lead":"Особовий займенник має дві форми: <b>підмета</b> (хто діє?) і <b>додатка</b> (кого? кому? — після дієслова та прийменника).","groups":[{"title":"Однина","note":"підмет → додаток","items":[["I","me"],["you","you"],["he","him"],["she","her"],["it","it"]]},{"title":"Множина","note":"підмет → додаток","items":[["we","us"],["you","you"],["they","them"]]},{"title":"Після прийменника","note":"завжди додаток","items":[["with","with me"],["for","for them"],["between you and","between you and me"]]}],"notes":["У коротких відповідях — форма додатка: <i>'Who's there?' 'It's <b>me</b>.'</i> / <i>'Who wants tea?' '<b>Me</b>!'</i>","Коли два підмети: <i>My sister and <b>I</b> went out.</i> (у формальній мові НЕ <s>me and my sister went</s>)","Займенник НЕ дублює підмет: <s>My father he works in a bank.</s>"]}$g19$::jsonb, null, 2
