insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g21$th_3$g21$, $g22$It і there: «порожній» підмет$g22$, $g23$intermediate$g23$, $g24$formula$g24$, $g25${"step":"It і there","kicker":"Речення без підмета неможливе","lead":"Там, де в українській підмета немає («Холодно», «Далеко»), англійська ставить <b>it</b> або <b>there</b>.","tiles":[{"role":"погода, час, відстань, оцінка","label":"it","tone":"opinion"},{"role":"щось існує, є десь","label":"there is / are","tone":"colour"}],"examples":[{"text":"<b>It</b>'s raining. / <b>It</b>'s five o'clock. / <b>It</b>'s 30 km to the airport.","plain":"It's raining. It's five o'clock. It's 30 kilometres to the airport.","note":"it"},{"text":"<b>It</b> takes two hours to get there. / <b>It</b>'s nice to see you.","plain":"It takes two hours to get there. It's nice to see you.","note":"it"},{"text":"<b>There</b> is a café near here. / <b>There</b> are a lot of people today.","plain":"There is a café near here. There are a lot of people today.","note":"there"}],"note":"<b>Типові помилки:</b> <s>Is raining.</s> → <i>It is raining.</i> · <s>It is many people here.</s> → <i>There are many people here.</i>","tabs":[{"title":"Тварини","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Для тварин зазвичай вживаємо <b>it</b>, а для домашніх улюбленців — часто <b>he / she</b>.</p>"}]}$g25$::jsonb, null, 3
