insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g27$th_5$g27$, $g28$Присвійні: my чи mine?$g28$, $g29$elementary$g29$, $g30$pairs$g30$, $g31${"step":"My чи mine","kicker":"Чиє?","lead":"<b>My</b>-форма стоїть ПЕРЕД іменником. <b>Mine</b>-форма стоїть САМА, без іменника: <i>Is this <b>your</b> bag? — No, it isn't <b>mine</b>. It's <b>hers</b>.</i>","groups":[{"title":"Однина","note":"+ іменник → без іменника","items":[["my","mine"],["your","yours"],["his","his"],["her","hers"],["its","—"]]},{"title":"Множина","note":"+ іменник → без іменника","items":[["our","ours"],["your","yours"],["their","theirs"]]}],"notes":["Присвійна форма НІКОЛИ не має апострофа: <i>hers, yours, ours, theirs, its</i> (НЕ <s>her's</s>, <s>your's</s>).","Присвійна форма НЕ поєднується з артиклем: <s>the my book</s> → <i>my book</i>.","Перед частинами тіла й одягом англійська ставить присвійний займенник: <i>He put <b>his</b> hands in <b>his</b> pockets.</i> (укр. «руки в кишені»)"]}$g31$::jsonb, null, 4
