insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g33$th_6$g33$, $g34$A friend of mine, own, its / it's, whose / who's$g34$, $g35$intermediate$g35$, $g36$cases$g36$, $g37${"step":"Of mine, own, its","kicker":"Окремі конструкції","lead":"Кілька конструкцій з присвійними, які варто знати окремо.","cards":[{"icon":"◆","title":"a friend of mine","text":"Один із моїх друзів. НЕ a my friend, НЕ a friend of me.","example":"Ann is <b>a friend of mine</b>.","examplePlain":"Ann is a friend of mine."},{"icon":"⌂","title":"my own / of my own","text":"Власний.","example":"I'd like to have <b>my own</b> room.","examplePlain":"I'd like to have my own room."},{"icon":"☺","title":"on my own","text":"Сам, без нікого (= by myself).","example":"She lives <b>on her own</b>.","examplePlain":"She lives on her own."},{"icon":"≠","title":"its ≠ it's","text":"its — його/її (присвійне); it's = it is / it has.","example":"<b>It's</b> raining.","examplePlain":"It's raining."},{"icon":"?","title":"whose ≠ who's","text":"whose — чий; who's = who is / who has.","example":"<b>Who's</b> coming tonight?","examplePlain":"Who's coming tonight?"}]}$g37$::jsonb, null, 5
