insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g39$th_7$g39$, $g40$Зворотні займенники: myself, yourself…$g40$, $g41$elementary$g41$, $g42$pairs$g42$, $g43${"step":"Зворотні","kicker":"Сам себе","lead":"Зворотний займенник вживаємо, коли <b>підмет і додаток — та сама особа</b>: дія повертається на того, хто її виконує.","groups":[{"title":"Однина","note":"особа → зворотний","items":[["I","myself"],["you","yourself"],["he","himself"],["she","herself"],["it","itself"]]},{"title":"Множина","note":"особа → зворотний","items":[["we","ourselves"],["you","yourselves"],["they","themselves"]]},{"title":"Сталі вирази","note":"значення → вираз","items":[["гарно провести час","enjoy yourself"],["пригощайся","help yourself"],["поводься чемно","behave yourself"],["почувайся як удома","make yourself at home"]]}],"notes":["<i>She looked at <b>herself</b> in the mirror.</i> Порівняйте: <i>I cut <b>myself</b></i> — себе, <i>I cut <b>him</b></i> — когось іншого.","<i>yourself</i> — до однієї людини, <i>yourselves</i> — до кількох.","Форм <s>hisself</s> і <s>theirselves</s> не існує."]}$g43$::jsonb, null, 6
