insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g45$th_8$g45$, $g46$Стоп-калька: дієслова на «-ся» без -self$g46$, $g47$intermediate$g47$, $g48$traps$g48$, $g49${"step":"Стоп-калька «-ся»","kicker":"Захист від рідної мови","lead":"Українське «-ся» не перекладається автоматично як <b>-self</b>. Багато англійських дієслів уже містять це значення: <i>wash, shave, dress, feel, relax, concentrate, meet, hurry (up), wonder, complain, worry, remember, get up, sit down</i>.","items":[{"title":"«Я почуваюся краще»","bad":"I feel myself better.","good":"I <b>feel</b> better.","goodPlain":"I feel better.","rule":"<i>feel</i> = почуватися, -self не потрібен."},{"title":"«Розслабся»","bad":"Relax yourself.","good":"<b>Relax</b>.","goodPlain":"Relax.","rule":"<i>relax</i> уже означає «розслабитися»."},{"title":"«Не можу зосередитися»","bad":"I can't concentrate myself.","good":"I can't <b>concentrate</b>.","goodPlain":"I can't concentrate.","rule":"<i>concentrate</i> = зосередитися."},{"title":"«Ми познайомилися в університеті»","bad":"We met ourselves at university.","good":"We <b>met</b> at university.","goodPlain":"We met at university.","rule":"<i>meet</i> = познайомитися."},{"title":"«Він умився, поголився, одягнувся»","bad":"He washed himself, shaved himself…","good":"He got up, <b>washed</b>, <b>shaved</b> and <b>got dressed</b>.","goodPlain":"He got up, washed, shaved and got dressed.","rule":"З <i>wash, dress, shave</i> -self можливий лише для наголосу: <i>She's only three, but she can dress herself.</i>"}]}$g49$::jsonb, null, 7
