insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g51$th_9$g51$, $g52$Підсилювальне -self, by myself, each other$g52$, $g53$intermediate$g53$, $g54$formula$g54$, $g55${"step":"-self чи each other","kicker":"Сам чи одне одного","lead":"Зворотний займенник може <b>підсилювати</b> («сам, особисто»), а для взаємної дії є окремі займенники.","tiles":[{"role":"кожен сам себе","label":"-selves","tone":"opinion"},{"role":"один одного","label":"each other · one another","tone":"colour"}],"legend":[{"tone":"opinion","label":"Kate and Paul looked at themselves. — кожен на себе"},{"tone":"colour","label":"Kate and Paul looked at each other. — вона на нього, він на неї"}],"examples":[{"text":"I painted it <b>myself</b>.","plain":"I painted it myself.","note":"сам, без допомоги"},{"text":"I went on holiday <b>by myself</b>.","plain":"I went on holiday by myself.","note":"сам = on my own"},{"text":"They help <b>one another</b>.","plain":"They help one another.","note":"трохи формальніше"},{"text":"We use <b>each other's</b> cars.","plain":"We use each other's cars.","note":"присвійна форма"}],"note":"<i>one another</i> = <i>each other</i>, але звучить трохи формальніше й частіше стосується групи."}$g55$::jsonb, null, 8
