insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g57$th_10$g57$, $g58$This / these – that / those$g58$, $g59$elementary$g59$, $g60$formula$g60$, $g61${"step":"This чи that","kicker":"Близько чи далеко","lead":"Вказівні займенники розрізняють за <b>числом</b> і за <b>відстанню</b> — у просторі та в часі.","tiles":[{"role":"тут, тепер · однина","label":"this","tone":"opinion"},{"role":"тут, тепер · множина","label":"these","tone":"size"},{"role":"там, тоді · однина","label":"that","tone":"colour"},{"role":"там, тоді · множина","label":"those","tone":"origin"}],"examples":[{"text":"<b>This</b> room is quite spacious.","plain":"This room is quite spacious.","note":"мовець тут"},{"text":"I'm seeing George <b>this</b> Friday.","plain":"I'm seeing George this Friday.","note":"теперішнє / майбутнє"},{"text":"<b>That</b> woman over there is the director.","plain":"That woman over there is the director.","note":"далеко"},{"text":"<b>That</b> month was the best.","plain":"That month was the best.","note":"минуле"}],"note":"<b>That</b> також посилається на щойно сказане: <i>'We're getting engaged!' '<b>That</b>'s marvellous!'</i>","tabs":[{"title":"Телефон і знайомство","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Хто говорить або кого представляємо — <b>this</b>; хто на тому кінці дроту — <b>that</b>:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">'Liz, <b>this</b> is Mary.'<br>Hello, <b>this</b> is Stephen.<br>Who's <b>that</b>, please?</div>"},{"title":"Без іменника","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">Вказівні можуть стояти без іменника:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\"><b>That</b>'s how he survived the shipwreck.</div>"}]}$g61$::jsonb, null, 9
