insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g63$th_11$g63$, $g64$A lot of / many / much$g64$, $g65$elementary$g65$, $g66$formula$g66$, $g67${"step":"Many чи much","kicker":"Скільки?","lead":"Вибір залежить від двох речей: чи <b>злічуваний</b> іменник і який <b>тип речення</b>.","tiles":[{"role":"ствердження","label":"a lot of / lots of","tone":"opinion"},{"role":"? і – · злічувані","label":"many","tone":"size"},{"role":"? і – · незлічувані","label":"much","tone":"colour"}],"examples":[{"text":"There are <b>a lot of</b> books in the library.","plain":"There are a lot of books in the library.","note":"ствердження"},{"text":"He's got <b>lots of</b> patience.","plain":"He's got lots of patience.","note":"ствердження"},{"text":"Are there <b>many</b> paintings?","plain":"Are there many paintings?","note":"питання"},{"text":"I don't have <b>much</b> money.","plain":"I don't have much money.","note":"заперечення"}],"note":"Після <b>how, so, too</b> — many / much навіть у ствердженні: <i>how much, so many, too much</i>.","tabs":[{"title":"Таблиця","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">countable</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">uncountable</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">(+)</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">a lot of / lots of / many (формально)</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">a lot of / lots of / much (формально)</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">(?)</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">many</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">much</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">(–)</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">many</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">much</td></tr></tbody>\n</table></div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\">У розмовній мові <i>a lot of</i> можливе і в питаннях: <i>Were there a lot of arguments?</i></p>"},{"title":"Формальні синоніми","html":"<div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">a large number of + countable<br>a great deal of + uncountable<br>plenty of + обидва (= більш ніж достатньо)</div>"}]}$g67$::jsonb, null, 10
