insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g69$th_12$g69$, $g70$A few / few, a little / little$g70$, $g71$intermediate$g71$, $g72$formula$g72$, $g73${"step":"Few чи a few","kicker":"Настрій кількості","lead":"Артикль <b>a</b> повністю змінює настрій: <i>a few</i> — «трохи, і це добре», <i>few</i> — «мало, майже нічого».","tiles":[{"role":"злічувані · +","label":"a few","tone":"age"},{"role":"злічувані · –","label":"few","tone":"origin"},{"role":"незлічувані · +","label":"a little","tone":"age"},{"role":"незлічувані · –","label":"little","tone":"origin"}],"legend":[{"tone":"age","label":"позитивно: трохи, вистачає"},{"tone":"origin","label":"негативно: мало, замало"}],"examples":[{"text":"Ann has <b>a little</b> flour left, so she'll make <b>a few</b> cakes.","plain":"Ann has a little flour left, so she'll make a few cakes.","note":"позитивно"},{"text":"<b>Few</b> people are allowed to meet the Queen.","plain":"Few people are allowed to meet the Queen.","note":"негативно"},{"text":"I've had <b>very little</b> response.","plain":"I've had very little response.","note":"негативно"}],"note":"<i>few / little</i> звучать формально; у розмові частіше <i>very few, very little, only a few, only a little</i>.","tabs":[{"title":"Коли потрібне of","html":"<p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><b>+ of</b>, якщо далі є <i>the, this/that/these/those</i>, присвійне або займенник:</p><div class=\"font-mono text-body-sm text-text-primary leading-relaxed mb-3\">How much <b>of the</b> money…?<br>many <b>of my</b> books · some <b>of them</b></div><p class=\"text-body-sm text-text-secondary leading-relaxed mb-3\"><b>Типова помилка:</b> <s>many of books</s> → <i>many books</i></p>"}]}$g73$::jsonb, null, 11
