insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g75$th_13$g75$, $g76$Some / any / no / every та їхні похідні$g76$, $g77$elementary$g77$, $g78$formula$g78$, $g79${"step":"Some чи any","kicker":"Хтось, щось, десь","lead":"Від <b>some, any, no, every</b> утворюються похідні для людей (-body / -one), речей (-thing) і місць (-where).","tiles":[{"role":"ствердження, пропозиції","label":"some","tone":"opinion"},{"role":"питання, заперечення","label":"any","tone":"size"},{"role":"= not any","label":"no","tone":"origin"},{"role":"усі","label":"every","tone":"age"}],"examples":[{"text":"Would you like <b>something</b> to drink?","plain":"Would you like something to drink?","note":"пропозиція → some"},{"text":"He didn't do <b>anything</b>.","plain":"He didn't do anything.","note":"заперечення → any"},{"text":"There's <b>no</b> news. = There isn't <b>any</b> news.","plain":"There's no news. There isn't any news.","note":"no = not any"},{"text":"<b>Every</b> candidate <b>has</b> to complete a form.","plain":"Every candidate has to complete a form.","note":"every + однина"}],"note":"<b>some</b> вживаємо і в проханнях: <i>Could I have <b>some</b> water?</i>","tabs":[{"title":"Таблиця похідних","html":"<div class=\"overflow-x-auto mb-3\"><table class=\"w-full text-body-sm border-collapse\">\n  <thead><tr><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\"></th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">люди</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">речі</th><th class=\"text-left text-caption-bold uppercase tracking-wider text-text-muted border-b border-border-default px-2.5 py-2\">місця</th></tr></thead>\n  <tbody><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">(+) some</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">someone / somebody</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">something</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">somewhere</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">(?) any</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">anyone / anybody</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">anything</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">anywhere</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">(–) no</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">no one / nobody</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">nothing</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">nowhere</td></tr><tr><td class=\"border-b border-border-default px-2.5 py-2 text-text-secondary\">усі: every</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">everyone / everybody</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">everything</td><td class=\"border-b border-border-default px-2.5 py-2 font-mono text-text-primary\">everywhere</td></tr></tbody>\n</table></div>"}]}$g79$::jsonb, null, 12
