insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g81$th_14$g81$, $g82$Тонкощі: any у ствердженні, одне заперечення, else$g82$, $g83$intermediate$g83$, $g84$cases$g84$, $g85${"step":"Тонкощі any","kicker":"Винятки з правила","lead":"У базовому правилі є кілька винятків, на яких найчастіше помиляються. Головне — в англійському реченні лише <b>одне</b> заперечення.","cards":[{"icon":"✕","title":"Одне заперечення","text":"Два заперечення в одному реченні неможливі: НЕ I didn't see nobody.","example":"I didn't see <b>anybody</b>. / I saw <b>nobody</b>.","examplePlain":"I didn't see anybody. I saw nobody."},{"icon":"∀","title":"any = будь-який","text":"У ствердженні any означає «будь-який».","example":"Take <b>anything</b> you like.","examplePlain":"Take anything you like."},{"icon":"?","title":"any після if","text":"В умовних реченнях — any-форми.","example":"If you let <b>anyone</b> in, you'll be in trouble.","examplePlain":"If you let anyone in, you'll be in trouble."},{"icon":"✓","title":"some у питанні","text":"Коли чекаємо відповіді «так».","example":"Is there <b>someone</b> in the garden?","examplePlain":"Is there someone in the garden?"},{"icon":"↓","title":"hardly, never, seldom","text":"Вони вже заперечують, тому після них — any-форми. Так само після without.","example":"She <b>seldom</b> goes <b>anywhere</b>.","examplePlain":"She seldom goes anywhere."},{"icon":"1","title":"Однина після -body","text":"Похідні на -body / -one / -thing — дієслово в однині.","example":"Everybody <b>is</b> here. / Nobody <b>knows</b>.","examplePlain":"Everybody is here. Nobody knows."},{"icon":"+","title":"else","text":"Ще, інший — після -one / -thing / -where. НЕ other something.","example":"someone <b>else</b> · anything <b>else</b> · nowhere <b>else</b>","examplePlain":"someone else, anything else, nowhere else"},{"icon":"∅","title":"no чи none","text":"no — перед іменником, none — без іменника.","example":"There's <b>no</b> time. — 'Any biscuits?' '<b>None</b>.'","examplePlain":"There's no time. Any biscuits? None."}]}$g85$::jsonb, null, 13
