insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g87$th_15$g87$, $g88$Other / another / the other / others / the others$g88$, $g89$intermediate$g89$, $g90$cases$g90$, $g91${"step":"Other чи another","kicker":"Інший","lead":"Усі ці форми означають «інший», але різняться числом і тим, чи йдеться про <b>конкретний залишок</b> групи.","cards":[{"icon":"+1","title":"another","text":"Ще один, будь-який: + однина або без іменника (another one).","example":"Would you like <b>another</b> cup of tea?","examplePlain":"Would you like another cup of tea?"},{"icon":"◌","title":"other / others","text":"Якісь інші, не всі: other + множина; others — без іменника.","example":"Some people like coffee, <b>others</b> prefer tea.","examplePlain":"Some people like coffee, others prefer tea."},{"icon":"2","title":"the other","text":"Другий із двох.","example":"One is a doctor, <b>the other</b> is a teacher.","examplePlain":"I have two brothers. One is a doctor, the other is a teacher."},{"icon":"∴","title":"the others","text":"Усі решта з конкретної групи (= the other + множина).","example":"Only Mark came on time. <b>The others</b> were late.","examplePlain":"Only Mark came on time. The others were late."},{"icon":"#","title":"another + число","text":"Ще стільки-то: another + число + множина.","example":"<b>another</b> three days · <b>another</b> 20 minutes","examplePlain":"another three days, another twenty minutes"},{"icon":"✕","title":"Типові помилки","text":"another уже містить an; other перед іменником не має -s.","example":"<s>an another</s> · <s>others students</s>","examplePlain":"another, other students"}]}$g91$::jsonb, null, 14
