insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g93$th_16$g93$, $g94$Both / all / none$g94$, $g95$intermediate$g95$, $g96$formula$g96$, $g97${"step":"Both, all, none","kicker":"Двоє чи більше","lead":"Ключ до вибору — <b>скільки</b> людей чи речей: два чи більше.","tiles":[{"role":"двоє · так","label":"both","tone":"opinion"},{"role":"двоє · ні","label":"neither","tone":"size"},{"role":"3+ · так","label":"all","tone":"colour"},{"role":"3+ · ні","label":"none","tone":"origin"}],"examples":[{"text":"<b>Both</b> boys are students. / They are <b>both</b> students.","plain":"Both boys are students. They are both students.","note":"дієслово у множині"},{"text":"<b>All</b> the children laughed. / They <b>all</b> laughed.","plain":"All the children laughed. They all laughed."},{"text":"<b>None of</b> the boys know(s) how to ride a bike.","plain":"None of the boys knows how to ride a bike.","note":"однина або множина"},{"text":"<b>All</b> that she did <b>was</b> stare at him.","plain":"All that she did was stare at him.","note":"all that = єдине, що"}],"note":"Позиція: both / all стоять після <i>be</i> і допоміжного дієслова, але перед основним: <i>They <b>are both</b> late. / They <b>both enjoyed</b> it.</i>"}$g97$::jsonb, null, 15
