insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g99$th_17$g99$, $g100$Either / neither / every / each / whole / one(s)$g100$, $g101$intermediate$g101$, $g102$cases$g102$, $g103${"step":"Each, every, either","kicker":"Кожен, будь-який, жоден","lead":"Ці слова вживаються з <b>однинним</b> злічуваним іменником, але мають різні відтінки.","cards":[{"icon":"½","title":"either","text":"Будь-який із двох."},{"icon":"∅","title":"neither","text":"Жоден із двох.","example":"<b>Neither</b> boy likes spaghetti.","examplePlain":"Neither boy likes spaghetti."},{"icon":"↻","title":"every","text":"Кожен, усі разом (3+), регулярно, без винятків.","example":"She cooks lunch <b>every</b> day.","examplePlain":"She cooks lunch every day."},{"icon":"•","title":"each","text":"Кожен окремо (від двох). Тільки each має форму з of: each of — але every one of, НЕ every of.","example":"<b>Each</b> student was awarded a diploma.","examplePlain":"Each student was awarded a diploma."},{"icon":"◯","title":"whole","text":"Цілий — після детермінанта. НЕ whole the morning.","example":"<b>the whole</b> morning = all morning","examplePlain":"the whole morning, all morning"},{"icon":"1","title":"one / ones","text":"Щоб не повторювати злічуваний іменник.","example":"'Which car is yours?' 'That <b>one</b>.'","examplePlain":"Which car is yours? That one."}]}$g103$::jsonb, null, 16
