insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g105$th_18$g105$, $g106$Both…and / either…or / neither…nor / not only…but also$g106$, $g107$advanced$g107$, $g108$formula$g108$, $g109${"step":"Парні сполучники","kicker":"Узгодження з дієсловом","lead":"Парні сполучники поєднують два підмети або дві дії. Головне питання — <b>з якою частиною</b> узгоджується дієслово.","tiles":[{"role":"дієслово у множині","label":"both … and","tone":"opinion"},{"role":"за найближчим підметом","label":"either … or · neither … nor","tone":"colour"}],"legend":[{"tone":"opinion","label":"both … and → завжди множина"},{"tone":"colour","label":"either … or · neither … nor · not only … but also → як найближчий підмет"}],"examples":[{"text":"<b>Both</b> Frank <b>and</b> Terry <b>enjoy</b> scuba diving.","plain":"Both Frank and Terry enjoy scuba diving.","note":"множина"},{"text":"<b>Either</b> Dr Green <b>or</b> Dr Howe <b>will</b> see you.","plain":"Either Dr Green or Dr Howe will see you."},{"text":"<b>Neither</b> Paula <b>nor</b> Sue and Clare <b>are</b> in the office.","plain":"Neither Paula nor Sue and Clare are in the office.","note":"найближчий — множина"},{"text":"<b>Neither</b> Justin <b>nor</b> Andrew <b>watches</b> TV.","plain":"Neither Justin nor Andrew watches TV.","note":"найближчий — однина"}],"note":"<b>Neither … nor</b> уже заперечне, друге заперечення зайве: <s>Neither Jane nor Victoria hasn't…</s>"}$g109$::jsonb, null, 17
