insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g111$th_19$g111$, $g112$Стоп-калька: займенники$g112$, $g113$elementary$g113$, $g114$traps$g114$, $g115${"step":"Стоп-калька","kicker":"Типові помилки","lead":"Найтиповіші помилки теми. Інші пастки — <i>its / it's</i>, «-ся» без -self, <i>an another</i> — розібрані у своїх кроках вище.","items":[{"title":"«Моя мама — лікар»","bad":"My mother she is a doctor.","good":"My mother <b>is</b> a doctor.","goodPlain":"My mother is a doctor.","rule":"Займенник не дублює підмет."},{"title":"«Сьогодні холодно»","bad":"Is cold today.","good":"<b>It</b> is cold today.","goodPlain":"It is cold today.","rule":"Речення без підмета неможливе — ставимо <i>it</i>."},{"title":"«Ця книжка твоя»","bad":"This book is your.","good":"This book is <b>yours</b>.","goodPlain":"This book is yours.","rule":"Без іменника — форма <i>yours</i>."},{"title":"«Мій друг» (один із)","bad":"a my friend","good":"<b>a friend of mine</b>","goodPlain":"a friend of mine","rule":"Артикль і присвійне разом не вживаються."},{"title":"«Усі тут»","bad":"Everybody are here.","good":"Everybody <b>is</b> here.","goodPlain":"Everybody is here.","rule":"Після -body / -one — дієслово в однині."},{"title":"«Я нічого не сказав»","bad":"I didn't say nothing.","good":"I didn't say <b>anything</b>.","goodPlain":"I didn't say anything.","rule":"В англійському реченні лише одне заперечення."}]}$g115$::jsonb, null, 18
