insert into public.theory_blocks (topic_id, block_key, title, level, kind, content_json, content_html, position)
select id, $g117$th_4$g117$, $g118$Узагальнені you / one / they та singular they$g118$, $g119$advanced$g119$, $g120$prose$g120$, null, $g121$
        <p class="text-slate-600 mb-3">Коли йдеться про <strong>людей загалом</strong>, англійська вживає займенники там, де українська обходиться безособовим реченням («Тут не можна палити»).</p>
        <div class="bg-indigo-50 border border-indigo-100 p-3 rounded-lg text-sm mb-3">
          <strong>you</strong> — розмовне «будь-хто» · <strong>one</strong> — формальне · <strong>they</strong> — «вони там», влада, інші люди
        </div>
        <ul class="text-xs space-y-1 text-slate-700">
          <li>• <em><strong>You</strong> can't smoke here.</em> — тут не можна палити (нікому)</li>
          <li>• <em><strong>One</strong> should always be polite.</em> — формально, книжно</li>
          <li>• <em><strong>They</strong> say it's going to be a cold winter.</em> — кажуть, що…</li>
          <li>• <strong>Singular they:</strong> після someone, anyone, everyone, nobody, а також коли стать невідома — <em>Someone left <strong>their</strong> umbrella. / Everyone did <strong>their</strong> best.</em></li>
          <li>• У формальному стилі трапляється <em>his or her</em>, але <em>their</em> — природна норма сучасної англійської.</li>
        </ul>
      $g121$, 19
