  ($g1235$pron_abcd_34$g1235$, $g1236$abcd$g1236$, $g1237$advanced$g1237$, $g1238${"id":"pron_abcd_34","level":"advanced","q":"34. Neither the teacher nor the students ______ the answer.","options":["A) knows","B) know","C) doesn't know","D) don't know"],"correct":1,"explanation":"Узгодження з найближчим підметом (students); neither…nor уже заперечне."}$g1238$, 33),
  ($g1239$pron_abcd_35$g1239$, $g1240$abcd$g1240$, $g1241$advanced$g1241$, $g1242${"id":"pron_abcd_35","level":"advanced","q":"35. Both Ann ______ her sister speak French.","options":["A) or","B) nor","C) and","D) but"],"correct":2,"explanation":"Пара both … and."}$g1242$, 34),
  ($g1243$pron_abcd_36$g1243$, $g1244$abcd$g1244$, $g1245$advanced$g1245$, $g1246${"id":"pron_abcd_36","level":"advanced","q":"36. Not only my brother but also my parents ______ coming.","options":["A) is","B) are","C) was","D) be"],"correct":1,"explanation":"Найближчий підмет — parents (множина) → are."}$g1246$, 35),
  ($g1247$pron_abcd_37$g1247$, $g1248$abcd$g1248$, $g1249$advanced$g1249$, $g1250${"id":"pron_abcd_37","level":"advanced","q":"37. If anyone calls, tell ______ I'll be back at five.","options":["A) it","B) its","C) them","D) one"],"correct":2,"explanation":"Після anyone природне singular they/them."}$g1250$, 36),
  ($g1251$pron_abcd_38$g1251$, $g1252$abcd$g1252$, $g1253$advanced$g1253$, $g1254${"id":"pron_abcd_38","level":"advanced","q":"38. ______ say that prices will rise again next year.","options":["A) One","B) They","C) It","D) There"],"correct":1,"explanation":"They say = кажуть (люди загалом)."}$g1254$, 37),
  ($g1255$pron_abcd_39$g1255$, $g1256$abcd$g1256$, $g1257$advanced$g1257$, $g1258${"id":"pron_abcd_39","level":"advanced","q":"39. There's been ______ rain this summer that the river has almost dried up.","options":["A) so few","B) so little","C) so many","D) so much"],"correct":1,"explanation":"Rain — незлічуваний: so little = так мало."}$g1258$, 38),
  ($g1259$pron_abcd_40$g1259$, $g1260$abcd$g1260$, $g1261$advanced$g1261$, $g1262${"id":"pron_abcd_40","level":"advanced","q":"40. I've read ______ books by this author — all twelve of them!","options":["A) every","B) each","C) all the","D) both"],"correct":2,"explanation":"Every і each вимагають однини, both — лише про двох; для дванадцяти книжок у множині — all the."}$g1262$, 39)
) as v(lid, type, level, payload, pos)
on conflict (legacy_id) where student_id is null do update set
  topic_id = excluded.topic_id, type = excluded.type, level = excluded.level,
  payload = excluded.payload, position = excluded.position;

commit;

-- Контроль: блоки теорії за рівнями та кількість вправ за типами
select 'теорія' as що, tb.level as деталь, count(*) from public.theory_blocks tb join public.topics t on t.id = tb.topic_id
  where t.slug = $g1268$pronouns$g1268$ group by tb.level
union all
select 'вправи', e.type, count(*) from public.exercises e join public.topics t on t.id = e.topic_id
  where t.slug = $g1269$pronouns$g1269$ and e.student_id is null group by e.type order by 1, 2;
